/* ==========================================================================
   ENCRYPTED PHOTO VAULT FOR NGUYEN BICH THAO
   Encrypted binary data bundle - Decrypted in-memory client-side at runtime
   ========================================================================== */
(function () {
  'use strict';

  var KEY = [0x54, 0x68, 0x61, 0x6F, 0x32, 0x30, 0x31, 0x30, 0x47, 0x69, 0x66, 0x74];
  var VAULT = {
  "1": "",
  "2": "",
  "3": "",
  "4": "",
  "5": ""
};

  window.__THAO_PHOTOS__ = {};

  function decryptToUrl(b64) {
    try {
      var bin = atob(b64);
      var len = bin.length;
      var bytes = new Uint8Array(len);
      for (var i = 0; i < len; i++) {
        bytes[i] = bin.charCodeAt(i) ^ KEY[i % KEY.length];
      }
      var blob = new Blob([bytes], { type: 'image/jpeg' });
      return URL.createObjectURL(blob);
    } catch (e) {
      console.error('Vault decryption error:', e);
      return '';
    }
  }

  // Decrypt all 5 photos into memory Blob URLs
  for (var k in VAULT) {
    if (Object.prototype.hasOwnProperty.call(VAULT, k)) {
      window.__THAO_PHOTOS__[k] = decryptToUrl(VAULT[k]);
    }
  }

  window.getThaoPhotoUrl = function (idx) {
    return window.__THAO_PHOTOS__[idx] || '';
  };

  function populateVaultImages() {
    document.querySelectorAll('[data-photo-idx]').forEach(function (el) {
      var idx = el.getAttribute('data-photo-idx');
      var url = window.getThaoPhotoUrl(idx);
      if (!url) return;
      var img = el.tagName === 'IMG' ? el : el.querySelector('img');
      if (img) {
        img.src = url;
      }
    });
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', populateVaultImages);
  } else {
    populateVaultImages();
  }
})();
